//#CTL2

function integer transform() {
    $out.0.study_visit_id = $in.0.study_visit_id;
    if (isnull($in.3.room_concept)) {
        $out.0.study_outcome = "DECLINED";
        $out.0.confirmed_nights = 0L;
        $out.0.adjusted_nightly_rate = 0D;
        $out.0.research_stay_value = 0D;
        $out.0.review_note = "ROOM_CONCEPT_UNKNOWN";
        return ALL;
    }
    if ($in.3.prototype_stage != "APPROVED") {
        $out.0.study_outcome = "DECLINED";
        $out.0.confirmed_nights = 0L;
        $out.0.adjusted_nightly_rate = 0D;
        $out.0.research_stay_value = 0D;
        $out.0.review_note = "PROTOTYPE_NOT_APPROVED";
        return ALL;
    }
    long usableResearchCapacity = nvl($in.2.research_nights, 0L) - $in.2.blocked_nights;
    if (usableResearchCapacity < 0L) usableResearchCapacity = 0L;
    long plannedNights = nvl($in.0.planned_nights, 0L);
    long confirmedNights = usableResearchCapacity < plannedNights ? usableResearchCapacity : plannedNights;
    if (confirmedNights == plannedNights) {
        $out.0.study_outcome = "CONFIRMED";
        $out.0.review_note = null;
    } else if (confirmedNights > 0L) {
        $out.0.study_outcome = "PARTIALLY_CONFIRMED";
        $out.0.review_note = "LIMITED_PILOT_CAPACITY";
    } else {
        $out.0.study_outcome = "WAITLISTED";
        $out.0.review_note = "NO_RESEARCH_CAPACITY";
    }
    $out.0.confirmed_nights = confirmedNights;
    decimal rebatePercent = 0D;
    if (!isnull($in.1.partner_class) && !isnull($in.1.rebate_percent)) {
        if (!isnull($in.0.arrival_day) && !isnull($in.1.campaign_open) && !isnull($in.1.campaign_close)
            && $in.0.arrival_day >= $in.1.campaign_open && $in.0.arrival_day <= $in.1.campaign_close) {
            rebatePercent = $in.1.rebate_percent;
        } else if ($in.1.trial_track == "LONG_STAY" && plannedNights >= nvl($in.1.qualifying_nights, 0L)) {
            rebatePercent = $in.1.rebate_percent;
        }
    }
    decimal nightlyRate = nvl($in.0.nightly_rate_lcy, 0D);
    decimal adjustedRate = nightlyRate * (1D - rebatePercent / 100D);
    decimal minimumRate = nightlyRate * nvl($in.3.minimum_rate_percent, 0.0) / 100D;
    if (adjustedRate < minimumRate) adjustedRate = minimumRate;
    $out.0.adjusted_nightly_rate = round(adjustedRate, 2);
    $out.0.research_stay_value = round($out.0.adjusted_nightly_rate * confirmedNights, 2);
    return ALL;
}
