//#CTL2

function integer transform() {
    $out.0.application_number = $in.0.application_number;

    if (isnull($in.1.citizen_reference)) {
        $out.0.payment_decision = "REVIEW";
        $out.0.sanctioned_rupees = 0D;
        $out.0.transfer_charge_rupees = 0D;
        $out.0.net_disbursement_rupees = 0D;
        $out.0.decision_reason = "CITIZEN_RECORD_NOT_FOUND";
        return ALL;
    }
    if (isnull($in.2.scheme_reference)) {
        $out.0.payment_decision = "REVIEW";
        $out.0.sanctioned_rupees = 0D;
        $out.0.transfer_charge_rupees = 0D;
        $out.0.net_disbursement_rupees = 0D;
        $out.0.decision_reason = "SCHEME_NOT_FOUND";
        return ALL;
    }

    if ($in.1.identity_verification_state != "VERIFIED"
        || isnull($in.1.annual_household_income)
        || $in.1.annual_household_income > $in.2.income_ceiling_rupees
        || ($in.2.biometric_confirmation_required && !$in.0.biometric_confirmed)) {
        $out.0.payment_decision = "REVIEW";
        $out.0.sanctioned_rupees = 0D;
        $out.0.transfer_charge_rupees = 0D;
        $out.0.net_disbursement_rupees = 0D;
        $out.0.decision_reason = "INELIGIBLE_OR_INCOMPLETE";
        return ALL;
    }

    if (isnull($in.3.disbursement_route)
        || $in.0.application_date < $in.3.channel_valid_from
        || (!isnull($in.3.channel_valid_to)
            && $in.0.application_date > $in.3.channel_valid_to)) {
        $out.0.payment_decision = "REVIEW";
        $out.0.sanctioned_rupees = 0D;
        $out.0.transfer_charge_rupees = 0D;
        $out.0.net_disbursement_rupees = 0D;
        $out.0.decision_reason = "PAYMENT_CHANNEL_UNAVAILABLE";
        return ALL;
    }

    decimal sanctioned = $in.2.base_assistance_rupees
        + $in.2.dependant_allowance_rupees * $in.0.eligible_dependant_count;
    sanctioned = min(sanctioned, $in.0.requested_rupees);
    sanctioned = round(sanctioned, 2);
    decimal transferCharge = round(sanctioned * $in.3.transfer_charge_pct / 100D, 2);

    $out.0.payment_decision = "APPROVED";
    $out.0.sanctioned_rupees = sanctioned;
    $out.0.transfer_charge_rupees = transferCharge;
    $out.0.net_disbursement_rupees = round(sanctioned - transferCharge, 2);
    $out.0.decision_reason = null;
    return ALL;
}
